// TickChildren ticks child state machines (W3C SCXML 6.4).
// Port of Rust do_tick_children().
func (p *StaticInvokeHybridPolicy) TickChildren(engine *sce.Engine[StaticInvokeHybridState, StaticInvokeHybridEvent]) {
	if !p.pendingDoneInvokeFirstRun && p.childFirstRun != nil {
		child := p.childFirstRun
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "first_run", engine)
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "first_run", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeFirstRun {
			p.pendingDoneInvokeFirstRun = true
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("first_run", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeSecondRun && p.childSecondRun != nil {
		child := p.childSecondRun
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "second_run", engine)
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "second_run", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeSecondRun {
			p.pendingDoneInvokeSecondRun = true
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("second_run", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeLossyRun && p.childLossyRun != nil {
		child := p.childLossyRun
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "lossy_run", engine)
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "lossy_run", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeLossyRun {
			p.pendingDoneInvokeLossyRun = true
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("lossy_run", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeMissingRun && p.childMissingRun != nil {
		child := p.childMissingRun
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "missing_run", engine)
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "missing_run", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeMissingRun {
			p.pendingDoneInvokeMissingRun = true
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("missing_run", child.DonedataAtFinal(), engine)
		}
	}
}

// NextChildDeadline reports the nearest deadline among the running children
// (W3C SCXML 6.4), so a host that walks time by TimeUntilNextScheduled does not
// step over a timer a child armed. The ticking above is what makes it this
// machine's. A child that has ended (pendingDoneInvoke) is skipped: the policy
// keeps it until its state exits, and what it armed is no longer owed.
func (p *StaticInvokeHybridPolicy) NextChildDeadline() (time.Duration, bool) {
	var soonest time.Duration
	found := false
	if !p.pendingDoneInvokeFirstRun && p.childFirstRun != nil {
		if due, ok := p.childFirstRun.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	if !p.pendingDoneInvokeSecondRun && p.childSecondRun != nil {
		if due, ok := p.childSecondRun.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	if !p.pendingDoneInvokeLossyRun && p.childLossyRun != nil {
		if due, ok := p.childLossyRun.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	if !p.pendingDoneInvokeMissingRun && p.childMissingRun != nil {
		if due, ok := p.childMissingRun.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	return soonest, found
}


// DeliverToInvocation delivers a delayed `<send target="#_<invokeid>">` whose
// wait is over, by name — a child need not declare every event its parent
// sends (W3C SCXML 6.2 + 6.4). It answers whether the invocation was there to
// take it: one whose session has reached its final state has ended, and the
// engine reports the send it could not deliver (W3C SCXML C.1).
func (p *StaticInvokeHybridPolicy) DeliverToInvocation(invokeID, eventName, eventData, sendID string) bool {
	if invokeID == "first_run" {
		if child := p.childFirstRun; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData)
			return true
		}
		return false
	}
	if invokeID == "second_run" {
		if child := p.childSecondRun; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData)
			return true
		}
		return false
	}
	if invokeID == "lossy_run" {
		if child := p.childLossyRun; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData)
			return true
		}
		return false
	}
	if invokeID == "missing_run" {
		if child := p.childMissingRun; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData)
			return true
		}
		return false
	}
	return false
}

// IsInvocationRunning reports whether `#_<invokeid>` names an invocation running
// now (W3C SCXML 6.4 + C.1) — one whose session has reached its final state has
// ended, and a send naming it is reported when it is made.
func (p *StaticInvokeHybridPolicy) IsInvocationRunning(invokeID string) bool {
	if invokeID == "first_run" {
		child := p.childFirstRun
		return child != nil && !child.IsInFinalState()
	}
	if invokeID == "second_run" {
		child := p.childSecondRun
		return child != nil && !child.IsInFinalState()
	}
	if invokeID == "lossy_run" {
		child := p.childLossyRun
		return child != nil && !child.IsInFinalState()
	}
	if invokeID == "missing_run" {
		child := p.childMissingRun
		return child != nil && !child.IsInFinalState()
	}
	return false
}



