// InitialState returns the initial state (W3C SCXML 3.3).
func (p *StaticInvokeHybridPolicy) InitialState() StaticInvokeHybridState {
	return StaticInvokeHybridStateFirst
}

// IsFinalState returns true if state is a <final> state (W3C SCXML 3.7).
func (p *StaticInvokeHybridPolicy) IsFinalState(state StaticInvokeHybridState) bool {
	switch state {
	case StaticInvokeHybridStateOver:
		return true
	}
	return false
}

// GetParent returns the parent of state, or (zero, false) if root (W3C SCXML 3.3).
func (p *StaticInvokeHybridPolicy) GetParent(state StaticInvokeHybridState) (StaticInvokeHybridState, bool) {
	switch state {
	case StaticInvokeHybridStateFirst:
		return StaticInvokeHybridStateRun, true
	case StaticInvokeHybridStateLossy:
		return StaticInvokeHybridStateRun, true
	case StaticInvokeHybridStateMissing:
		return StaticInvokeHybridStateRun, true
	case StaticInvokeHybridStateSecond:
		return StaticInvokeHybridStateRun, true
	}
	return 0, false
}

// IsCompoundState returns true if state is a <state> with child states — exactly
// the states that have an initial transition. A <parallel> is not compound
// (W3C SCXML 3.3).
func (p *StaticInvokeHybridPolicy) IsCompoundState(state StaticInvokeHybridState) bool {
	return len(initialTargetsOfStaticInvokeHybrid[state]) > 0
}

func (p *StaticInvokeHybridPolicy) IsParallelState(_ StaticInvokeHybridState) bool { return false }

